   [13]={next_id=14, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="医疗区在大楼的地下一层，需要通过一部专用电梯才能到达。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [14]={next_id=15, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="电梯门已经被人从里面砸开了，门板上留着几个深深的手印。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [15]={next_id=16, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="走廊很长，两侧是一间间独立的病房。门都开着，里面空空荡荡。走廊尽头，最大的一间病房里，传出了组特的声音。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
