   [28]={next_id=29, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他们还说艾朵的病症十分特殊，必须留在专属病房接受特殊治疗，这一切都是为了她好……我居然傻乎乎的全部信了……", msg_color="", msg_size=0, talker="组特", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
