   [46]={next_id=47, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="绿色粉末（民用精力剂）：\n主要成分由星彩源晶尘埃、高浓度虚粒子提取物、某种特殊生物的花粉构成。长期微量摄入会造成肺部不可逆纤维化，即为矿区俗称的“晶肺”。\n负面影响：短期加大剂量摄入，会加速人体内虚粒子暴走，逐步完成异变转化。", msg_color="", msg_size=0, talker="实验记录", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
