   [73]={next_id=74, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你们继续向着地底前进。走廊尽头矗立着一扇厚重的钢制防火门，门框严密紧实。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_303.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [74]={next_id=75, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="原本配有高级电子密码锁，此刻锁芯被暴力损毁，门板向内凹陷，边缘布满狰狞的撞击裂痕，想来是先前异变体暴走冲撞所致。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_303.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [75]={next_id=76, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这应该就是通往地下应急通道的入口。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_303.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [76]={next_id=77, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你抬手推了推防火门，沉重的铁门应声而动，露出一道可供两人并排通行的幽暗通道。通道下方漆黑一片，看不到尽头，阴冷潮湿的气流从深处涌出，裹挟着复杂怪异的气味。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_303.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
